const sourceJson = $json || {};
const rawText = String(sourceJson.snippet || "")
  .replace(/\r/g, "")
  .trim();
const text = rawText.replace(/\n+/g, "\n");

function toStr(v) {
  return String(v ?? "").trim();
}

function pickField(lines, labels) {
  const escaped = labels.map((l) => l.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const re = new RegExp(`^(?:${escaped.join("|")})\\s*[:：\\-]?\\s*(.+)$`, "i");
  for (const line of lines) {
    const m = line.match(re);
    if (m && m[1]) return toStr(m[1]);
  }
  return "";
}

function firstMatch(s, re) {
  const m = s.match(re);
  return m ? toStr(m[1] || m[0]) : "";
}

function compactText(v) {
  return toStr(v).replace(/\s+/g, " ").trim();
}

function extractEmail(s) {
  const m = String(s || "").match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return m ? m[0].toLowerCase() : "";
}

function normalizePhone(raw) {
  const src = toStr(raw);
  if (!src) return "";
  const plus = src.startsWith("+");
  const digits = src.replace(/\D/g, "");
  if (digits.length < 10 || digits.length > 15) return "";
  return `${plus ? "+" : ""}${digits}`;
}

function extractPhoneFromText(s) {
  const candidates = String(s || "").match(/(?:\+?7|8)?[\s(\-]*\d{3}[\s)\-]*\d{3}[\s\-]*\d{2}[\s\-]*\d{2}/g) || [];
  for (const c of candidates) {
    const n = normalizePhone(c);
    if (n) return n;
  }
  return "";
}

function isEmailDomain(domain, fullText) {
  const lower = String(fullText || "").toLowerCase();
  const emails = lower.match(/[a-z0-9._%+-]+@([a-z0-9.-]+\.[a-z]{2,})/g) || [];
  return emails.some((e) => e.endsWith(`@${domain.toLowerCase()}`));
}

function extractSite(explicitValue, fullText) {
  const cleanExplicit = toStr(explicitValue).replace(/[),.;:!?]+$/g, "");
  if (cleanExplicit) return cleanExplicit;

  const urlMatch = String(fullText || "").match(/https?:\/\/[^\s)]+/i);
  if (urlMatch) return toStr(urlMatch[0]).replace(/[),.;:!?]+$/g, "");

  const domainMatch = String(fullText || "").match(/\b(?:[a-z0-9-]+\.)+[a-z]{2,}\b/i);
  if (!domainMatch) return "";

  const domain = domainMatch[0].replace(/[),.;:!?]+$/g, "");
  if (isEmailDomain(domain, fullText)) return "";
  return domain;
}

function extractMessenger(s) {
  const full = String(s || "");
  const tgHandle = full.match(/(^|\s)(@[a-zA-Z0-9_]{5,32})\b/);
  if (tgHandle) return tgHandle[2];

  const tgLink = full.match(/https?:\/\/(?:t\.me|telegram\.me)\/[^\s)]+/i);
  if (tgLink) return tgLink[0].replace(/[),.;:!?]+$/g, "");

  const waLink = full.match(/https?:\/\/(?:wa\.me|api\.whatsapp\.com)\/[^\s)]+/i);
  if (waLink) return waLink[0].replace(/[),.;:!?]+$/g, "");

  const waPhone = full.match(/(?:whatsapp|ватсап|вацап|wa)\s*[:\-]?\s*(\+?\d[\d\s()\-]{8,}\d)/i);
  if (waPhone) {
    const n = normalizePhone(waPhone[1]);
    if (n) return `WhatsApp: ${n}`;
  }

  return "";
}

const lines = text.split("\n").map((l) => l.trim()).filter(Boolean);

const clientName =
  pickField(lines, ["Имя", "Ваше имя", "ФИО", "От кого"]) ||
  "UNKNOWN";

const explicitPhone = pickField(lines, ["Телефон", "Контакт"]);
let clientPhone = normalizePhone(explicitPhone);
if (!clientPhone) clientPhone = extractPhoneFromText(text);

const explicitEmail = pickField(lines, ["E-mail", "Email", "Почта"]);
const clientEmail = extractEmail(explicitEmail || text);

const messengerLabel = pickField(lines, ["Мессенджер"]);
const contactLine = pickField(lines, ["Контакт"]);
const clientMessenger = extractMessenger(`${messengerLabel}\n${contactLine}\n${text}`);

const explicitSite = pickField(lines, ["Адрес сайта", "Сайт", "URL"]);
const clientSite = extractSite(explicitSite, text);

const page =
  pickField(lines, ["Отправлено со страницы", "Страница", "URL страницы"]) ||
  firstMatch(text, /(https?:\/\/[^\s]+)\s*$/i);

const ip =
  pickField(lines, ["IP", "IP-адрес"]) ||
  firstMatch(text, /\b((?:\d{1,3}\.){3}\d{1,3})\b/);

const comment =
  pickField(lines, ["Комментарий", "Сообщение", "Вопрос", "Текст заявки"]);

const calcMatches = [...text.matchAll(/(?:^|\n)\s*((?:0[1-9]|1\d|20))\s*[:：]\s*([^\n]+)/g)];
const calcData = calcMatches
  .map((m) => `${m[1]}: ${compactText(m[2])}`)
  .join("; ");
const calcDetected = calcMatches.length > 0;

const requestText = [compactText(comment), calcData]
  .filter(Boolean)
  .join(calcData && comment ? " | " : "");

let contactType = "unknown";
if (clientPhone) {
  contactType = "phone";
} else if (clientEmail) {
  contactType = "email";
} else if (clientMessenger) {
  contactType = "messenger";
}

const clientContact = clientPhone || clientEmail || clientMessenger || "UNKNOWN";

const gmailMessageId = sourceJson.id || "";
const gmailThreadId = sourceJson.threadId || "";

return [{
  json: {
    gmail_message_id: gmailMessageId,
    gmail_thread_id: gmailThreadId,
    lead_id: gmailMessageId || String(Date.now()),
    created_at: new Date(Number(sourceJson.internalDate || Date.now())).toISOString(),
    source: "gmail",
    email_subject: sourceJson.subject || "UNKNOWN",
    client_name: clientName,
    contact_type: contactType,
    client_contact: clientContact,
    client_phone: clientPhone,
    client_email: clientEmail,
    client_messenger: clientMessenger,
    client_site: clientSite,
    request_text: requestText,
    request_page: page,
    ip,
    raw_text: text,
    calc_detected: calcDetected,
    calc_data: calcData,
    utm_source: firstMatch(text, /(?:\butm_source\b|UTM Source)\s*[:=]\s*([^\s&\n]+)/i),
    utm_medium: firstMatch(text, /(?:\butm_medium\b|UTM Medium)\s*[:=]\s*([^\s&\n]+)/i),
    utm_campaign: firstMatch(text, /(?:\butm_campaign\b|UTM Campaign)\s*[:=]\s*([^\s&\n]+)/i),
    utm_term: firstMatch(text, /(?:\butm_term\b|UTM Term)\s*[:=]\s*([^\s&\n]+)/i),
    utm_content: firstMatch(text, /(?:\butm_content\b|UTM Content)\s*[:=]\s*([^\s&\n]+)/i),
    ai_summary: "",
    ai_detected_service: "",
    ai_priority: "",
    ai_reply: "",
    manager_status: "new",
    processing_status: "parsed"
  }
}];

const lead = $node["Lead-Mail-Parser"].json;

return [{
  json: {
    ...lead,
    openrouter_body: {
      model: "openai/gpt-4o-mini",
      messages: [
        {
          role: "system",
          content: "Ты помощник менеджера веб-студии i-SEO. Анализируй входящие заявки кратко и по делу. Определи услугу строго одним значением: Audit, SEO, Direct, Site, Other. Верни только валидный JSON без markdown и без пояснений."
        },
        {
          role: "user",
          content: `Проанализируй лид.

Сырые данные:
${lead.raw_text}

Дополнительно:
Имя: ${lead.client_name}
Контакт: ${lead.client_contact}
Сайт: ${lead.client_site}
Страница: ${lead.request_page}
Калькулятор: ${lead.calc_data}

Правила услуги:
- Audit = SEO-аудит, аудит сайта, заявка на проверку, анализ или оценку продвижения
- SEO = SEO-продвижение, органический трафик, поисковая оптимизация
- Direct = Яндекс Директ, контекстная реклама, performance ads, настройка рекламы
- Site = разработка сайта, лендинг, редизайн, доработка сайта, техническая задача по сайту
- Other = неясно или не относится к услугам

Верни JSON строго в формате:
{
  "ai_summary": "",
  "ai_detected_service": "Audit|SEO|Direct|Site|Other",
  "ai_priority": "low|normal|high",
  "ai_reply": "",
  "quality_status": "ok|warning|bad",
  "quality_comment": ""
}`
        }
      ],
      temperature: 0.2
    }
  }
}];

const lead = $node["Lead-Mail-Parser"].json;

let content = "";

try {
  content = $json.choices?.[0]?.message?.content || "";
} catch (e) {
  content = "";
}

let ai = {};

try {
  ai = JSON.parse(content);
} catch (e) {
  ai = {
    ai_summary: "AI_PARSE_FAILED",
    ai_detected_service: "Other",
    ai_priority: "normal",
    ai_reply: ""
  };
}

return [
  {
    json: {
      ...lead,

      ai_summary: ai.ai_summary || "",
      ai_detected_service: ai.ai_detected_service || "Other",
      ai_priority: ai.ai_priority || "normal",
      ai_reply: ai.ai_reply || ""
    }
  }
];

const raw = $node["Normalize-AI-Result"].json;

let content = $json.choices?.[0]?.message?.content || "";
let clean = {};

try {
  clean = JSON.parse(content);
} catch (e) {
  clean = {
    clean_name: raw.client_name,
    primary_contact: raw.client_contact,
    phone: raw.client_phone,
    email: raw.client_email,
    messenger: raw.client_messenger,
    site: raw.client_site,
    service: raw.ai_detected_service || "Other",
    summary: raw.ai_summary,
    quality_status: "warning",
    quality_comment: "AI не смог корректно разобрать данные лида."
  };
}

function cleanText(value) {
  return String(value || "")
    .replace(/^'+/, "")
    .replace(/^=+'+/, "")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanSite(value) {
  const site = cleanText(value);
  if (!site) return "";
  if (site === "." || site === "-" || site === "—") return "";
  if (/Комментарий:/i.test(site)) return "";
  if (/Отправлено со страницы:/i.test(site)) return "";
  return site;
}

const allowedServices = new Set(["Audit", "SEO", "Direct", "Site", "Other"]);
let service = cleanText(clean.service || raw.ai_detected_service || "Other");
service = allowedServices.has(service) ? service : "Other";

const allowedQuality = new Set(["ok", "warning", "bad"]);
let qualityStatus = cleanText(clean.quality_status || "warning").toLowerCase();
qualityStatus = allowedQuality.has(qualityStatus) ? qualityStatus : "warning";

const qualityComment = cleanText(clean.quality_comment);
const summaryBase = cleanText(clean.summary || raw.ai_summary);
const summaryWithContext = [
  summaryBase,
  raw.request_page ? `Страница: ${cleanText(raw.request_page)}` : "",
  raw.calc_data ? `Калькулятор: ${cleanText(raw.calc_data)}` : ""
].filter(Boolean).join(" | ");

return [{
  json: {
    lead_id: raw.lead_id,
    created_at: raw.created_at,
    clean_name: cleanText(clean.clean_name || raw.client_name),
    primary_contact: cleanText(clean.primary_contact || raw.client_contact),
    phone: cleanText(clean.phone || raw.client_phone),
    email: cleanText(clean.email || raw.client_email),
    messenger: cleanText(clean.messenger || raw.client_messenger),
    site: cleanSite(clean.site) || cleanSite(raw.client_site),
    service,
    summary: summaryWithContext,
    ai_reply: cleanText(raw.ai_reply),
    quality_status: qualityStatus,
    quality_comment: qualityComment,
    duplicate_status: "unknown",
    manager_status: "new",
    notes: ""
  }
}];

