const lead = $node["Normalize-AI-Result"].json;

return [{
  json: {
    ...lead,
    openrouter_body: {
      model: "openai/gpt-4o-mini",
      messages: [
        {
          role: "system",
          content: "Ты нормализатор лидов. Приводи данные к чистому виду, убирай мусор, определяй основной контакт, услугу и качество данных. Верни только валидный JSON без markdown и без пояснений. Услуга должна быть строго одной из: Audit, SEO, Direct, Site, Other."
        },
        {
          role: "user",
          content: `Нормализуй данные лида:

Имя: ${lead.client_name}
Тип связи: ${lead.contact_type}
Контакт: ${lead.client_contact}
Телефон: ${lead.client_phone}
Email: ${lead.client_email}
Мессенджер: ${lead.client_messenger}
Сайт: ${lead.client_site}
Комментарий: ${lead.request_text}
Страница: ${lead.request_page}
Калькулятор: ${lead.calc_data}
AI summary: ${lead.ai_summary}
AI service: ${lead.ai_detected_service}

Правила услуги:
- Audit = SEO-аудит, аудит сайта, заявка на проверку, анализ или оценку продвижения
- SEO = SEO-продвижение, органический трафик, поисковая оптимизация
- Direct = Яндекс Директ, контекстная реклама, performance ads, настройка рекламы
- Site = разработка сайта, лендинг, редизайн, доработка сайта, техническая задача по сайту
- Other = неясно или не относится к услугам

Верни JSON строго в формате:
{
  "clean_name": "",
  "primary_contact": "",
  "phone": "",
  "email": "",
  "messenger": "",
  "site": "",
  "service": "Audit|SEO|Direct|Site|Other",
  "summary": "",
  "quality_status": "ok|warning|bad",
  "quality_comment": ""
}`
        }
      ],
      temperature: 0.1
    }
  }
}];

const lead = $node["Normalize-Clean-Lead"].json;

function onlyDigits(value) {
  return String(value || "").replace(/\D/g, "");
}

function cleanText(value) {
  return String(value || "")
    .replace(/^'+/, "")
    .replace(/^#ERROR!.*$/i, "")
    .trim()
    .toLowerCase();
}

function isRealMessenger(value) {
  const v = cleanText(value);
  if (!v) return false;
  if (["telegram", "whatsapp", "wa", "max", "телеграм", "ватсап", "вацап"].includes(v)) return false;
  return /^@/.test(v) || /t\.me\//.test(v) || onlyDigits(v).length >= 10;
}

const leadId = cleanText(lead.lead_id);
const leadPhone = onlyDigits(lead.phone || lead.primary_contact);
const leadEmail = cleanText(lead.email);
const leadMessenger = cleanText(lead.messenger);
const leadSite = cleanText(lead.site);

const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && Object.keys(row).length > 0);

const duplicates = rows.filter((row) => {
  const rowLeadId = cleanText(row.lead_id);
  const rowPhone = onlyDigits(row.phone || row.primary_contact);
  const rowEmail = cleanText(row.email);
  const rowMessenger = cleanText(row.messenger);
  const rowSite = cleanText(row.site);

  if (leadId && rowLeadId && leadId === rowLeadId) return true;
  if (leadPhone && rowPhone && leadPhone === rowPhone) return true;
  if (leadEmail && rowEmail && leadEmail === rowEmail) return true;
  if (isRealMessenger(leadMessenger) && isRealMessenger(rowMessenger) && leadMessenger === rowMessenger) return true;
  if (leadSite && rowSite && leadSite === rowSite) return true;

  return false;
});

let duplicateStatus = "new";
let duplicateNote = "";

if (duplicates.length > 0) {
  duplicateStatus = "repeat";

  const last = duplicates[duplicates.length - 1];

  duplicateNote = [
    "Повторный лид.",
    last.created_at ? `Предыдущее обращение: ${last.created_at}` : "",
    last.service ? `Прошлая услуга: ${last.service}` : "",
    last.summary ? `Прошлый смысл: ${last.summary}` : ""
  ]
    .filter(Boolean)
    .join(" ");
}

return [
  {
    json: {
      ...lead,
      duplicate_status: duplicateStatus,
      notes: duplicateNote
    }
  }
];
